text='a ``` b ````` c'
begin=2
start=begin
max_ticks=0
last=len(text)
while start<last and text[start]=='`':
    max_ticks+=1; start+=1
print('max_ticks',max_ticks,'start',start)  # start = 5 (after ```)
longest_span=0; end=0
i=start
while i<last:
    span_length=0
    while i<last and text[i]=='`':
        span_length+=1; i+=1
    if not span_length:
        i+=1; continue
    if max_ticks==span_length:
        print('exact',start,i-span_length); break
    if span_length>longest_span:
        longest_span=span_length; end=i
print('longest_span',longest_span,'end',end)
if longest_span:
    print('fallback', start-(max_ticks-longest_span), end-longest_span)
EOF"}

